@startuml

abstract class Well {
  + code : string
}

class OnshoreWell --|> Well {
  + surfaceExtension : float
}

class OffshoreWell --|> Well {
  + installationYear : int
  + geographicalAreaCode : string
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantityPerYear : float
}

Well "1" *-- "0..*" Extraction
Extraction "*" -- "1" OilCompany
Extraction "*" -- "1" Well

OffshoreWell "0..1" o-- "0..1" GeographicalArea

@enduml

